#!/usr/bin/env python3
"""Implementation of the logstat command as per SPEC.md.

The code follows the specification exactly: argument parsing, input parsing, error handling, and output formatting.
"""
import sys
import datetime

# Constants
LEVELS = ["DEBUG", "INFO", "WARN", "ERROR", "FATAL"]
LEVEL_ORDER = {lvl: i for i, lvl in enumerate(LEVELS)}
MIN_LEVEL_DEFAULT = "DEBUG"
NUMBER_DEFAULT = 3

# Helper functions

def error_exit(msg, code):
    # Print diagnostic to stderr and exit
    sys.stderr.write(msg + "\n")
    sys.exit(code)


def parse_args(argv):
    """Parse command line arguments.
    Returns (subcommand, options dict, file_path or None)
    Raises usage error via error_exit.
    """
    if not argv:
        error_exit("logstat: missing subcommand", 2)
    subcommand = argv[0]
    if subcommand not in {"count", "top", "span"}:
        error_exit(f"logstat: unknown subcommand {subcommand}", 2)
    options = {"min_level": MIN_LEVEL_DEFAULT, "number": None}
    file_paths = []
    i = 1
    while i < len(argv):
        arg = argv[i]
        if arg == "-":
            # literal file named '-'
            file_paths.append(arg)
        elif arg.startswith("-"):
            # option
            if arg.startswith("--min-level"):
                if arg == "--min-level":
                    if i + 1 >= len(argv):
                        error_exit("logstat: missing value for --min-level", 2)
                    val = argv[i + 1]
                    i += 1
                elif arg.startswith("--min-level="):
                    val = arg.split("=", 1)[1]
                else:
                    error_exit("logstat: malformed --min-level option", 2)
                if val not in LEVELS:
                    error_exit(f"logstat: invalid level {val}", 2)
                options["min_level"] = val
            elif arg.startswith("--number"):
                if subcommand != "top":
                    error_exit("logstat: --number option is only valid with top", 2)
                if arg == "--number":
                    if i + 1 >= len(argv):
                        error_exit("logstat: missing value for --number", 2)
                    val = argv[i + 1]
                    i += 1
                elif arg.startswith("--number="):
                    val = arg.split("=", 1)[1]
                else:
                    error_exit("logstat: malformed --number option", 2)
                if not val.isdigit() or int(val) < 1:
                    error_exit("logstat: --number must be a positive integer", 2)
                options["number"] = int(val)
            else:
                error_exit(f"logstat: unknown option {arg}", 2)
        else:
            # not an option, treat as file
            file_paths.append(arg)
        i += 1
    if len(file_paths) > 1:
        error_exit("logstat: more than one file specified", 2)
    file_path = file_paths[0] if file_paths else None
    return subcommand, options, file_path


def parse_timestamp(ts_str):
    # Expect exactly 20 chars
    if len(ts_str) != 20:
        return None
    try:
        dt = datetime.datetime.strptime(ts_str, "%Y-%m-%dT%H:%M:%SZ")
        # Ensure that formatted back matches exactly (strptime allows some flexibility like year 1-9999). Already pattern ensures.
        return dt
    except Exception:
        return None


def read_input(file_path):
    """Read all lines from file or stdin.
    Returns list of (line_number, line_str) with line_number starting at 1.
    Raises input error via error_exit if file cannot be opened.
    """
    lines = []
    if file_path is None:
        # read from stdin
        try:
            data = sys.stdin.read()
        except Exception:
            error_exit("logstat: cannot read from stdin", 3)
        # splitlines(False) keeps ending newline? We want lines without newline.
        raw = data.split("\n")
        # Note: if input ends with newline, split will produce last empty string; that's fine.
        for idx, line in enumerate(raw, start=1):
            lines.append((idx, line))
    else:
        try:
            with open(file_path, "rt", encoding="utf-8") as f:
                raw = f.read().split("\n")
            for idx, line in enumerate(raw, start=1):
                lines.append((idx, line))
        except Exception:
            error_exit("logstat: cannot open file", 3)
    return lines


def parse_records(lines, min_level):
    """Parse lines into records, checking for malformed.
    Returns list of dicts: {timestamp: str, level: str, service: str, message: str, dt: datetime}
    """
    min_index = LEVEL_ORDER[min_level]
    records = []
    malformed_line = None
    for line_no, raw_line in lines:
        # Determine if blank
        if raw_line.strip("\t ") == "":
            continue
        # Check record structure
        parts = raw_line.split("|", 3)
        if len(parts) < 4:
            malformed_line = malformed_line or line_no
            continue
        ts_str, level, service, message = parts
        # Validate timestamp
        dt = parse_timestamp(ts_str)
        if dt is None:
            malformed_line = malformed_line or line_no
            continue
        # Validate level
        if level not in LEVELS:
            malformed_line = malformed_line or line_no
            continue
        # Validate service not empty
        if service == "":
            malformed_line = malformed_line or line_no
            continue
        # Record is valid; apply min-level filter
        if LEVEL_ORDER[level] >= min_index:
            records.append({"timestamp": ts_str, "level": level, "service": service, "message": message, "dt": dt})
    if malformed_line is not None:
        error_exit(f"logstat: malformed record on line {malformed_line}", 4)
    return records


def run_count(records, min_level):
    min_index = LEVEL_ORDER[min_level]
    counts = {lvl: 0 for lvl in LEVELS}
    for rec in records:
        lvl = rec["level"]
        counts[lvl] += 1
    # Prepare output lines
    total = sum(counts[lvl] for lvl in LEVELS if LEVEL_ORDER[lvl] >= min_index)
    width = len(str(total)) if total > 0 else 1
    out_lines = []
    for lvl in LEVELS:
        if LEVEL_ORDER[lvl] >= min_index:
            out_lines.append(f"{lvl:<5} {counts[lvl]:>{width}}")
    out_lines.append(f"TOTAL  {total:>{width}}")
    sys.stdout.write("\n".join(out_lines) + "\n")


def run_top(records, number):
    # Count per service
    service_counts = {}
    for rec in records:
        service_counts[rec["service"]] = service_counts.get(rec["service"], 0) + 1
    # Sort
    sorted_services = sorted(service_counts.items(), key=lambda x: (-x[1], x[0]))
    top_services = sorted_services[:number]
    if not top_services:
        sys.exit(0)
    # Determine widths
    name_width = max(len(name) for name, _ in top_services)
    count_width = max(len(str(cnt)) for _, cnt in top_services)
    out_lines = []
    for name, cnt in top_services:
        out_lines.append(f"{name:<{name_width}} {cnt:>{count_width}}")
    sys.stdout.write("\n".join(out_lines) + "\n")


def run_span(records):
    if not records:
        error_exit("logstat: no records matched", 5)
    # Find min and max dt
    min_rec = min(records, key=lambda r: r["dt"])
    max_rec = max(records, key=lambda r: r["dt"])
    delta = int((max_rec["dt"] - min_rec["dt"]).total_seconds())
    out_lines = [
        f"first  {min_rec['timestamp']}",
        f"last   {max_rec['timestamp']}",
        f"secs   {delta}"
    ]
    sys.stdout.write("\n".join(out_lines) + "\n")


def main():
    subcommand, options, file_path = parse_args(sys.argv[1:])
    lines = read_input(file_path)
    records = parse_records(lines, options["min_level"])
    if subcommand == "count":
        if options["number"] is not None:
            error_exit("logstat: --number option is not allowed with count", 2)
        run_count(records, options["min_level"])
    elif subcommand == "top":
        num = options["number"] if options["number"] is not None else NUMBER_DEFAULT
        run_top(records, num)
    elif subcommand == "span":
        if options["number"] is not None:
            error_exit("logstat: --number option is not allowed with span", 2)
        run_span(records)
    else:
        # unreachable
        error_exit("logstat: unknown subcommand", 2)

if __name__ == "__main__":
    main()

